PAYLOAD_SHA256 = 'ea46f6e1d95dc4feeeb67d033b3d879f7e29f27921405bed9153ef1e45475f03'
ROOT = Path(__file__).resolve().parent


def sha(data):
    return hashlib.sha256(data).hexdigest()


def main():
    if not (ROOT / 'manage.py').is_file():
        raise RuntimeError('Place this script beside manage.py.')
    os.chdir(ROOT)
    lock = open(ROOT / '.workflow_v24_update.lock', 'a')
    os.chmod(ROOT / '.workflow_v24_update.lock', 0o600)
    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    logs = ROOT / 'logs'
    logs.mkdir(exist_ok=True)
    log_path = logs / 'workflow_v24_update.log'
    fd = os.open(log_path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
    with os.fdopen(fd, 'a', encoding='utf-8') as log:
        def say(message):
            print(message, flush=True)
            log.write(message + '\n')
            log.flush()

        def run(*args):
            log.flush()
            result = subprocess.run(
                [sys.executable, *args], cwd=ROOT, env=env,
                stdout=log, stderr=subprocess.STDOUT,
            )
            if result.returncode:
                raise RuntimeError('Command failed: ' + ' '.join(args[:3]))

        try:
            say('Starting customer workflow V24 update.')
            packed = base64.b64decode(''.join(PAYLOAD.split()), validate=True)
            if sha(packed) != PAYLOAD_SHA256:
                raise RuntimeError('Script payload is incomplete or changed. Copy the entire script again.')
            specs = json.loads(zlib.decompress(packed))
            updates = {}
            for name, spec in specs.items():
                path = ROOT / name
                if path.is_symlink() or not path.resolve().is_relative_to(ROOT):
                    raise RuntimeError('Unsafe file path: ' + name)
                raw = path.read_bytes() if path.exists() else None
                old = raw.replace(b'\r\n', b'\n') if raw is not None else None
                digest = sha(old) if old is not None else None
                if digest == spec['new']:
                    continue
                if digest == spec['old']:
                    edits = spec['edits']
                elif (digest or 'missing') in spec.get('variants', {}):
                    edits = spec['variants'][digest or 'missing']
                else:
                    raise RuntimeError('File differs from the supported version; no application files changed: ' + name)
                lines = old.decode('utf-8').splitlines(keepends=True) if old is not None else []
                for start, end, replacement in reversed(edits):
                    lines[start:end] = replacement.splitlines(keepends=True)
                new = ''.join(lines).encode('utf-8')
                if sha(new) != spec['new']:
                    raise RuntimeError('Patch verification failed: ' + name)
                if name.endswith('.py'):
                    compile(new, name, 'exec')
                updates[name] = new
            say('Verified all source files. Files to update: ' + str(len(updates)))
            env = os.environ.copy()
            env['DJANGO_SETTINGS_MODULE'] = 'crm.settings'
            info = subprocess.run(
                [sys.executable, '-c',
                 'import json; from django.conf import settings; '
                 'd=settings.DATABASES["default"]; '
                 'print(json.dumps({"engine":d["ENGINE"],"name":str(d["NAME"])}))'],
                cwd=ROOT, env=env, capture_output=True, text=True,
            )
            if info.returncode:
                log.write(info.stderr)
                raise RuntimeError('Cannot load existing Django settings; no application files changed.')
            database = json.loads(info.stdout)
            if database['engine'] != 'django.db.backends.sqlite3':
                raise RuntimeError('This installer requires the current SQLite development database; no application files changed.')
            db = Path(database['name'])
            if not db.is_absolute():
                db = ROOT / db
            if not db.is_file():
                raise RuntimeError('Existing SQLite database not found; no application files changed.')
            stamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
            backup = ROOT / 'backups' / ('workflow-v24-' + stamp)
            backup.mkdir(parents=True, mode=0o700)
            backup.chmod(0o700)
            for name in updates:
                source = ROOT / name
                if source.exists():
                    saved = backup / 'files' / name
                    saved.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(source, saved)
            with sqlite3.connect(db.resolve().as_uri() + '?mode=ro', uri=True) as source:
                with sqlite3.connect(backup / 'database.sqlite3') as target:
                    source.backup(target)
                    if target.execute('PRAGMA quick_check').fetchone()[0] != 'ok':
                        raise RuntimeError('Database backup verification failed.')
            (backup / 'database.sqlite3').chmod(0o600)
            say('Backup created: ' + str(backup))
            for name, content in updates.items():
                path = ROOT / name
                path.parent.mkdir(parents=True, exist_ok=True)
                mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
                fd, temporary = tempfile.mkstemp(prefix='.workflow-v24-', dir=path.parent)
                try:
                    with os.fdopen(fd, 'wb') as file:
                        file.write(content)
                        file.flush()
                        os.fsync(file.fileno())
                    os.chmod(temporary, mode)
                    os.replace(temporary, path)
                finally:
                    if os.path.exists(temporary):
                        os.unlink(temporary)
            say('Application files updated. Applying migrations...')
            run('manage.py', 'migrate', '--noinput')
            run('manage.py', 'check')
            run('manage.py', 'migrate', '--check')
            smoke = "import django\ndjango.setup()\nfrom django.conf import settings\nfrom crm.numerals import normalize_input\nfrom crm.pagination import PAGE_SIZE\nassert 'crm.feedback.FeedbackContextMiddleware' in settings.MIDDLEWARE\nassert PAGE_SIZE == 10\nassert normalize_input('①٢３ 𝟜५۶') == '123 456'\nassert normalize_input('۰۹۱۲٣۴۵۶۷۸۹') == '09123456789'\nassert normalize_input('۱٬۲۳۴٫۵۰') == '1234.50'\nassert 'crm.middleware.NormalizeNumeralInputsMiddleware' in settings.MIDDLEWARE\nfrom django.contrib.auth.models import User\nfrom django.contrib.messages.storage.fallback import FallbackStorage\nfrom django.template.loader import get_template\nfrom django.test import Client, RequestFactory\nfrom accounts.forms import UserCreateForm, UserEditForm\nfrom accounts.models import UserRoleProfile\nfrom accounts.permissions import PERMISSIONS, PERMISSION_META, ROLE_SECRETARY, ROLE_OPERATOR, ROLE_SALES_MANAGER\nfrom customers.models import Reception, FollowUp, CaseWorkSession, HiringAd, HiringAdSequence, HiringApplication, InterviewSession, HiringReferral\nfrom crm.private_files import HiringDocumentStorage\nReception.objects.values_list('arrived_at','timing_version').first()\nHiringApplication.objects.values_list('current_arrived_at','status','resume').first()\nInterviewSession.objects.values_list('arrived_at','started_at','ended_at','waiting_seconds').first()\nCaseWorkSession.objects.values_list('started_at','ended_at').first()\nHiringAd.objects.values_list('number','role_title').first()\nHiringAdSequence.objects.values_list('next_number').first()\nHiringReferral.objects.values_list('to_user_id').first()\nfrom hr.models import Task\nTask.objects.values_list('due_time','assigned_user_id','hiring_session_id','performed_session_id').first()\nget_template('customers/_interview_task_modal.html')\ntry:\n    HiringDocumentStorage().url('private')\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError('Hiring documents must not have public URLs')\nfrom customers.hub_views import customer_hub\nfrom calls.models import Call\nfrom calls.forms import CallForm\nfrom ads.models import Ad\nassert CallForm().fields['source'].required\nCall.objects.values_list('source_id','source_phone_snapshot','source_label_snapshot').first()\nAd.objects.values_list('source_phone_snapshot','source_label_snapshot','platform_name_snapshot','process_name_snapshot').first()\nassert set(PERMISSIONS) == set(PERMISSION_META)\nfor key in ('customers.hiring_interview','customers.hiring_refer','customers.hiring_ads','customers.hiring_documents'):\n    assert key in PERMISSION_META\nassert ROLE_SECRETARY in PERMISSIONS['customers.reception']\nassert ROLE_OPERATOR not in PERMISSIONS['customers.case']\nassert ROLE_SALES_MANAGER in PERMISSIONS['customers.registration']\nassert 'role_title' in UserCreateForm().fields\nassert 'role_title' in UserEditForm().fields\nUserRoleProfile.objects.values_list('display_name').first()\nReception.objects.values_list('workflow_version','referred_at','case_completed_at','registration_completed_at').first()\nFollowUp.objects.values_list('due_time').first()\nCall.objects.values_list('requested_condition','follow_up_time').first()\nfor name in ('includes/_form_styles.html','includes/_surface_styles.html','includes/_form_client.html','includes/_chart_ui.html','includes/_form_field.html','includes/_form_errors.html','includes/_import_steps.html','customers/_customer_fields.html','customers/form.html','customers/form_modal.html','products/form.html','sales/form.html','hr/employee_form.html','includes/_live_search.html','customers/_hiring_ads_list.html','admin/base_site.html','customers/_interview_modal.html','customers/_hiring_ad_modal.html','customers/_hiring_referral_modal.html','customers/_workflow_filters.html','includes/_source_search.html','ads/platform_list.html','ads/process_list.html','includes/_digit_glyphs.html','includes/_numerals.html','includes/_numeral_font.html','customers/_invoice_hub_details.html','customers/hub.html','customers/_reception_tab.html','customers/_case_tab.html','customers/_registration_tab.html','customers/_hiring_tab.html','customers/form_modal.html','accounts/user_form.html'):\n    get_template(name)\nhost = next((h for h in settings.ALLOWED_HOSTS if h != '*' and not h.startswith('.')), 'localhost')\nlogin = Client().get('/accounts/login/', secure=True, HTTP_HOST=host)\nassert login.status_code == 200\nadmin = User.objects.filter(is_active=True,is_superuser=True).first()\nif admin:\n    for tab in ('info','reception','case','registration','hiring','invoice'):\n        request = RequestFactory().get('/customers/hub/', {'tab':tab},secure=True,HTTP_HOST=host)\n        request.user=admin; request.session={}; request._messages=FallbackStorage(request)\n        response=customer_hub(request)\n        assert response.status_code == 200, (tab,response.status_code)\nprint('SMOKE CHECK PASSED: workflow schema, tab access, user forms, templates, login and all hub tabs.')\n"
            run('-c', smoke)
            restart = ROOT / 'tmp'
            restart.mkdir(exist_ok=True)
            (restart / 'restart.txt').touch()
            say('SUCCESS: files updated, migrations applied, checks passed, Passenger restart requested.')
            say('Reception -> referral -> case -> registration is ready. Existing records are preserved in the legacy archive.')
            say('Secretary: information + reception. Operator: information only. Supervisor: all hub tabs.')
            say('SMS remains TEST ONLY; no real SMS is sent.')
            say('Log: ' + str(log_path))
        except Exception as error:
            say('FAILED: ' + str(error))
            say('See logs/workflow_v24_update.log. Backups are preserved; the database is NOT automatically restored.')
            raise SystemExit(1)


if __name__ == '__main__':
    main()
